import os
def jpg_size(p):
    with open(p,'rb') as f:
        d=f.read()
    i=2
    while i<len(d):
        if d[i]!=0xFF: i+=1; continue
        m=d[i+1]
        if m in (0xC0,0xC1,0xC2,0xC3):
            h,w=unpack('>HH',d[i+5:i+9]); return w,h
        i+=2+unpack('>H',d[i+2:i+4])[0]
