  const [id, setId] = useState(null);
  useEffect(() => {
    api("/api/genres").then((r) => {
      if (!r.ok) return;
      const g = unwrapItems(r).find((x) => x.name === name);
      if (g) setId(g.id);
    });
  }, [name]);
  return id;
}

// Pick a featured (hero) title: top10 of `kind`, or first trending.
