import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { api, unwrapItems } from "../api";
import HeroBillboard from "../components/HeroBillboard";
import Rail from "../components/Rail";

export default function GenreCategory() {
  const { genreId } = useParams();
  const [genre, setGenre] = useState(null);
  const [titles, setTitles] = useState([]);
  const [notFound, setNotFound] = useState(false);

  useEffect(() => {
    let live = true;
    setGenre(null);
    setNotFound(false);
    api("/api/genres").then((g) => {
      if (!live || !g.ok) return;
      const row = unwrapItems(g).find((x) => x.id === parseInt(genreId, 10));
      if (!row) {
        setNotFound(true);
        return;
      }
      setGenre(row);
      api(`/api/genres/${row.id}/titles`).then((r) => {
        if (live && r.ok) setTitles(unwrapItems(r));
      });
    });
    return () => { live = false; };
  }, [genreId]);

  if (notFound) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center pt-[68px] text-[#999]">
        <div className="text-2xl mb-2">Genre not found</div>
        <a href="/browse" className="text-[#53c1de] hover:underline">Back to Home</a>
      </div>
    );
  }

  const hero = titles[0];
  const series = titles.filter((t) => t.kind === "series");
  const movies = titles.filter((t) => t.kind === "movie");

  return (
    <div className="pt-0 pb-10">
      {hero && <HeroBillboard title={hero} tall={false} />}
      <div className="relative z-10 -mt-8 md:-mt-10">
        <div className="px-4 md:px-[4vw] mb-2">
          <h2 className="text-lg md:text-xl font-semibold">{genre ? genre.name : "…"}</h2>
        </div>
        <Rail title={`Top Picks in ${genre ? genre.name : ""}`} items={titles} />
        {series.length > 0 && <Rail title={`${genre ? genre.name : ""} TV Shows`} items={series} />}
        {movies.length > 0 && <Rail title={`${genre ? genre.name : ""} Movies`} items={movies} />}
      </div>
    </div>
  );
}
import { useEffect, useState, useCallback } from "react";
import { api, unwrapItems } from "../api";
import { openTitleModal } from "../App";

export default function MyList() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(() => {
    api("/api/my-list").then((r) => {
      setLoading(false);
      if (r.ok) setItems(unwrapItems(r));
    });
  }, []);

  useEffect(() => { load(); }, [load]);

  const remove = async (row) => {
    await api(`/api/my-list/${row.id}`, { method: "DELETE" });
    setItems((prev) => prev.filter((x) => x.id !== row.id));
  };

  return (
    <div className="pt-[88px] pb-10 px-4 md:px-[4vw] min-h-screen">
      <h1 className="text-2xl md:text-3xl font-semibold mb-6">My List</h1>
      {loading ? (
        <div className="text-[#999]">Loading…</div>
      ) : items.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-24 text-center">
          <img src="/assets/icons/plus.svg" alt="" className="w-10 h-10 invert opacity-40 mb-4" />
          <div className="text-lg text-[#e5e5e5]">Your list is empty</div>
          <p className="mt-1 text-sm text-[#707070] max-w-md">
            Add shows and movies to keep track of everything you want to watch.
            Tap the + button on any title to add it here.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
          {items.map((t) => (
            <div key={t.id} className="group relative">
              <button
                onClick={() => openTitleModal(t.title_id)}
                className="w-full aspect-[2/3] rounded overflow-hidden bg-[#1f1f1f] relative"
              >
                <img src={t.poster} alt={t.name} className="w-full h-full object-cover" loading="lazy" />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-colors" />
              </button>
              <button
                onClick={() => remove(t)}
                aria-label={`Remove ${t.name} from My List`}
                className="absolute top-2 right-2 w-8 h-8 rounded-full bg-black/70 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity hover:bg-black"
              >
                <img src="/assets/icons/x.svg" alt="" className="w-4 h-4 invert" />
              </button>
              <div className="mt-1.5 text-[13px] truncate">{t.name}</div>
              <div className="text-[11px] text-[#707070]">
                {t.kind === "movie" ? "Movie" : "Series"} · {t.year}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

