  const [rating, setRating] = useState(null);

  useEffect(() => {
    let live = true;
    api(`/api/titles/${id}`).then((r) => {
      if (live && r.ok) setTitle(r.data.item);
    });
    return () => { live = false; };
  }, [id]);

  useEffect(() => {
    if (!title || title.kind !== "series") return;
    api(`/api/titles/${id}/episodes`).then((r) => {
      if (r.ok) setEpisodes(r.data.items || []);
    });
  }, [id, title && title.kind]);

