    if (r.ok) setInList(unwrapItems(r).some((m) => m.title_id === id));
  };
  useEffect(() => {
    checkList();
    api("/api/ratings").then((r) => {
      if (r.ok) {
        const row = unwrapItems(r).find((x) => x.title_id === id);
        setRating(row ? row.value : null);
      }
    });
  }, [id]);

