def rgb(name):
    return Image.open(f"{REF}/{name}.jpg").convert("RGB")

def row_bands(im, std_thresh=14, min_h=12):
    w, h = im.size
    px = im.load()
    runs = []
    start = None
    for y in range(h):
        vals = [px[x, y] for x in range(0, w, 4)]
        m = sum(vals) / len(vals)
