    for x in range(0, w):
        vals = [px[x, y] for y in range(y0, min(y1, h))]
        b = sum(1 for v in vals if v > thresh) / len(vals)
        if b > frac and start is None: start = x
        elif b <= frac and start is not None:
            if x - start >= min_w: runs.append((start, x - 1))
            start = None
    if start is not None and w - start >= min_w: runs.append((start, w - 1))
    return runs

def colmean(im, y0, y1, thresh=26, min_w=15):
