            if x - start >= min_w: runs.append((start, x - 1))
            start = None
    if start is not None and w - start >= min_w: runs.append((start, w - 1))
    return runs

def heatmap(name, cols=96, rows=40):
    im = load(name)
    w, h = im.size
    im2 = im.resize((cols, rows))
    px = im2.load()
    chars = " .:-=+*#%@"
    print(f"== {name} ({w}x{h})")
    for j in range(rows):
        line = ""
        for i in range(cols):
            v = px[i, j]
            line += chars[min(9, v // 26)]
        print(f"{j*h//rows:4d} {line}")

def map2d(name, x0, x1, y0, y1, res=10):
    im = load(name)
    px = im.load()
    w, h = im.size
    chars = " .:*#"
    print(f"== {name} x={x0}-{x1} y={y0}-{y1} @{res}px")
    for j in range((y1 - y0) // res):
        line = ""
        for i in range((x1 - x0) // res):
            tot = 0; n = 0
            for dy in range(0, res, 2):
                for dx in range(0, res, 3):
