                    if yy < h and xx < w:
                        tot += px[xx, yy]; n += 1
            m = tot / max(1, n)
            line += chars[min(4, int(m) // 52)]
        print(f"{y0+j*res:4d} {line}")

def red_rows(im, y0=0, y1=None, min_c=8, tag=""):
    im = rgb(im) if isinstance(im, str) else im
    px = im.load()
    w, h = im.size
    if y1 is None: y1 = h
