            if r + g + b > 90:
                rs += r; gs += g; bs += b; n += 1
    if not n:
        print(f"  {tag}: dark"); return
    print(f"  {tag}: n={n} avg=({rs//n},{gs//n},{bs//n})")

def cmd():
