            aria-label={`Play ${title.name}`}
            className="absolute left-[24.7vw] bottom-[2vh] text-left font-display text-[4.7vw] max-w-[60vw] leading-[1.05] uppercase text-white drop-shadow-lg hover:brightness-110"
          >
            {title.name}
          </button>
        </div>

        {/* centered content */}
        <div className="mx-auto w-[49.8vw] min-w-[680px] max-w-full">
          <div className="mt-[6vh] flex gap-[3vw]">
            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-3 text-[13px]">
                {title.rating != null && (
                  <span className="text-[#46d369] font-semibold">{Math.round(title.rating * 10)}% Match</span>
                )}
