    elif args[0] == "bands":
        for n in args[1:]:
            im = load(n)
            print(f"== {n} ({im.size}) row bands:")
            for a, b in row_bands(im):
                print(f"   y={a}-{b} (h={b-a+1}, {100*(b-a+1)/im.size[1]:.0f}%)")
    elif args[0] == "brow":
        for spec in args[1:]:
            n, x0, x1, y0, y1 = spec.split(",")
            im = load(n)
            print(f"{n} x={x0}-{x1} y={y0}-{y1}:")
            for a, b in bright_rows(im, int(x0), int(x1), int(y0), int(y1)):
                print(f"   y={a}-{b} (h={b-a+1})")
    elif args[0] == "bx":
        for spec in args[1:]:
            n, y0, y1 = spec.split(",")
            im = load(n)
            print(f"{n} y={y0}-{y1}:")
            for a, b in band_x(im, int(y0), int(y1)):
