            im = load(n)
            print(f"{n} y={y0}-{y1} colmean>26:")
            for a, b in colmean(im, int(y0), int(y1)):
                print(f"   x={a}-{b} (w={b-a+1})")

if __name__ == "__main__":
    cmd()
