    print(f"== {n} ({W}x{H})")
    chars = " .:-=+*#%@"
    for r in range(rows):
        y0 = r * H // rows; y1 = max(y0 + 1, (r + 1) * H // rows)
        line = ""
        for c in range(cols):
            x0 = c * W // cols; x1 = max(x0 + 1, (c + 1) * W // cols)
            s = 0; cnt = 0
            for y in range(y0, y1, 3):
                for x in range(x0, x1, 3):
                    s += px[x, y]; cnt += 1
            avg = s / cnt
            line += chars[min(9, int(avg / 25.6))]
        print(f"{y0:4d} {line}")

def map2d(n, x0, x1, y0, y1):
    im = load(n); px = im.load()
    step = 10
    print(f"== {n} x={x0}-{x1} y={y0}-{y1} @10px")
    for y in range(y0, y1, step):
        line = ""
        for x in range(x0, x1, step):
            m = max(px[x + dx, y + dy] for dx in range(0, step, 2) for dy in range(0, step, 2))
            line += " .:-=+*#%@" [min(9, int(m / 25.6))] if m < 256 else "@"
        print(f"{y:4d} {line}")

def row_bands(im):
    W, H = im.size; px = im.load()
    out = []; y = 0
    while y < H:
        n = sum(1 for x in range(0, W, 4) if px[x, y] > 90)
        if n > 4:
            a = y
            while y < H and sum(1 for x in range(0, W, 4) if px[x, y] > 90) > 4:
                y += 1
            out.append((a, y - 1))
        y += 1
    return out

def bright_rows(im, x0, x1, y0, y1):
    W, H = im.size; px = im.load()
    out = []; y = y0
    while y < min(y1, H):
        n = sum(1 for x in range(x0, x1, 3) if px[x, y] > 90)
        if n > 3:
            a = y
            while y < min(y1, H) and sum(1 for x in range(x0, x1, 3) if px[x, y] > 90) > 3:
                y += 1
            out.append((a, y - 1))
        y += 1
    return out

def band_x(im, y0, y1):
    W, H = im.size; px = im.load()
    on = [any(px[x, y] > 90 for y in range(y0, y1)) for x in range(W)]
