  const scroll = (dir) => {
    const el = scroller.current;
    if (!el) return;
    el.scrollBy({ left: dir * el.clientWidth * 0.9, behavior: "smooth" });
  };

  const cardVariant = numbered ? (variant || "top16") : "rail";

  return (
    <section className="relative mb-[4vh] group/rail">
      <h2 className="px-[3.5vw] mb-2.5 text-[17px] font-semibold text-[#e5e5e5] flex items-center gap-2">
