            while y<H and sum(1 for x in range(x0,x1,2) if px[x,y]>th)>minn: y+=1
            out.append((a,y-1))
        y+=1
    print(f"== {n} h-bands th={th} x={x0}-{x1}:")
    for a,b in out: print(f"   y={a:4d}-{b:4d} (h={b-a+1:3d})")

def vband(n, th, y0, y1, minn=3):
    im=load(n);px=im.load()
    W=im.size[0]
    on=[]
    for x in range(W):
        c=sum(1 for y in range(y0,y1,2) if px[x,y]>th)
        on.append(c>minn)
    out=[];s=None;p=None
    for x,o in enumerate(on):
        if o:
            if s is None: s=p=x
            elif x-p<=6: p=x
            else: out.append((s,p));s=p=x
        else:
            if s is not None: out.append((s,p));s=None
    if s is not None: out.append((s,p))
    print(f"== {n} v-bands th={th} y={y0}-{y1}:")
    for a,b in out:
        if b-a>=4: print(f"   x={a:4d}-{b:4d} (w={b-a+1:3d})")

def rect(n,x0,x1,y0,y1):
    im=load(n,"RGB");px=im.load()
