];

export default function RateDialog({ titleId, onClose }) {
  const [title, setTitle] = useState(null);
  const [current, setCurrent] = useState(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let live = true;
    api(`/api/titles/${titleId}`).then((r) => {
