  const [season, setSeason] = useState(parseInt(params.get("season") || "1", 10));
  const [epNo, setEpNo] = useState(parseInt(params.get("ep") || "1", 10));
  const [playing, setPlaying] = useState(true);
  const [current, setCurrent] = useState(0);
