import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { api, unwrapItems } from "../api";
import { openTitleModal } from "../App";

export default function GenreCategory() {
  const { genreId } = useParams();
  const nav = useNavigate();
  const [genre, setGenre] = useState(null);
  const [titles, setTitles] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [notFound, setNotFound] = useState(false);

  useEffect(() => {
    let live = true;
    setGenre(null); setTitles([]); setLoaded(false); setNotFound(false);
    api("/api/genres").then((g) => {
      if (!live || !g.ok) return;
      const row = unwrapItems(g).find((x) => x.id === parseInt(genreId, 10));
      if (!row) { setNotFound(true); setLoaded(true); return; }
      setGenre(row);
      api(`/api/genres/${row.id}/titles`).then((r) => {
        if (!live) return;
        setTitles(r.ok ? unwrapItems(r) : []);
        setLoaded(true);
      });
    });
    return () => { live = false; };
  }, [genreId]);

  if (notFound) { ... same as before ... }
  if (!loaded) return <div className="min-h-screen bg-nfg" />;

  const hero = titles[0];
  const top10 = new Set(titles.filter(t => t.top10_rank).map(t => t.id));
  const byYear = [...titles].sort((a,b) => (b.year||0)-(a.year||0));
  const freshIds = new Set(byYear.slice(0,4).map(t=>t.id));

  return (
    <div className="pt-0 pb-10">
      {hero && (
        <div className="relative w-full h-[78vh] min-h-[560px]">
          <img src={hero.backdrop || hero.poster} alt={hero.name} className="absolute inset-0 w-full h-full object-cover" />
          <div className="absolute inset-0 bg-gradient-to-r from-black/85 via-black/40 to-transparent" />
          <div className="absolute inset-x-0 bottom-0 h-[8vh] bg-gradient-to-t from-[#141414] to-transparent" />
          <div className="absolute top-[44.5vh] left-[3.6vw] max-w-[60vw]">
            <div className="text-[#e50914] font-bold tracking-[0.12em] uppercase text-[1.25vw] leading-none">
              Genres
            </div>
            <h1 className="mt-[2.2vh] font-display text-[6.4vw] leading-[1.04] text-white drop-shadow-lg">
              {genre ? genre.name : ""}
            </h1>
          </div>
        </div>
      )}
      {titles.length === 0 ? (
        <div className="px-[3.5vw] pt-[8vh] text-[#999]">No titles found in this genre yet.</div>
      ) : (
        <div className="px-[3.33vw] mt-[2vh]">
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-1.5">
            {titles.map((t, i) => (
              <div key={t.id + "-" + i} className="group">
                <button onClick={() => openTitleModal(t.id)}
                  className="w-full aspect-video rounded overflow-hidden bg-[#1f1f1f] relative block">
                  <img src={t.backdrop || t.poster} alt={t.name} className="w-full h-full object-cover" loading="lazy" />
