import sys
from PIL import Image

def load(p):
    im = Image.open(p).convert("RGB")
    return im, im.load(), im.size

def mask(im, x0, x1, y0, y1, bw=6, bh=4):
    """block-aggregated mask: # red, o bright>170, . mid>80 else space"""
    px = im.load()
    out = []
    for by in range(y0, min(y1, im.size[1]), bh):
        row = []
        for bx in range(x0, min(x1, im.size[0]), bw):
            r=g=b=0; n=0
            for y in range(by, min(by+bh, im.size[1]), max(1,bh//3)):
                for x in range(bx, min(bx+bw, im.size[0]), max(1,bw//3)):
                    r+=px[x,y][0]; g+=px[x,y][1]; b+=px[x,y][2]; n+=1
            r//=n; g//=n; b//=n
