    """grayscale ascii, optional horizontal subsample sw"""
    px = im.load()
    ramp = " .:-=+*#%@"
    out=[]
    for y in range(y0, min(y1, im.size[1]), 2):
        row=[]
        for x in range(x0, min(x1, im.size[0]), sw):
            v = sum(px[x,y])//3
            row.append(ramp[min(9, v*10//256)])
        out.append(''.join(row))
    return '\n'.join(out)

