    im, px, size = load(p)
    if cmd == "size":
        print(size)
    elif cmd == "mask":
        print(mask(im, int(sys.argv[3]), int(sys.argv[4]), int(sys.argv[5]), int(sys.argv[6]),
                   int(sys.argv[7]) if len(sys.argv)>7 else 6,
                   int(sys.argv[8]) if len(sys.argv)>8 else 4))
    elif cmd == "raw":
        print(raw(im, int(sys.argv[3]), int(sys.argv[4]), int(sys.argv[5]), int(sys.argv[6]),
                   int(sys.argv[7]) if len(sys.argv)>7 else 1))
