                  >
                    {g}
                  </Link>
                ))}
              </div>
            </div>
          </div>

          <div className="mt-4 flex items-center gap-3">
            {title.maturity_rating && (
              <span className="border border-[#6d6d6e] px-1.5 text-[12px] text-[#e5e5e5]">
