          {error && (
            <p className="text-[14px] text-[#e7b85a] bg-[#412c08]/40 border border-[#6a4b12] rounded px-3 py-2">
              {error}
            </p>
          )}
          {note && !error && (
            <p className="text-[13px] text-[#9c8f8f]">{note}</p>
          )}

