// API client — same-origin via the nginx proxy (/api, /auth -> backend).
const TOKEN_KEY = "nf_token";
const PROFILE_KEY = "nf_profile";

export function getToken() {
  return localStorage.getItem(TOKEN_KEY);
}
export function setToken(t) {
  if (t) localStorage.setItem(TOKEN_KEY, t);
  else localStorage.removeItem(TOKEN_KEY);
}
export function getProfileId() {
  return localStorage.getItem(PROFILE_KEY);
}
export function setProfileId(p) {
  if (p) localStorage.setItem(PROFILE_KEY, String(p));
  else localStorage.removeItem(PROFILE_KEY);
}

export async function api(path, { method = "GET", body } = {}) {
  const headers = {};
  if (body !== undefined) headers["Content-Type"] = "application/json";
  const token = getToken();
  if (token) headers["Authorization"] = "Bearer " + token;
  const profile = getProfileId();
  if (profile) headers["X-Profile-Id"] = profile;
  let res;
  try {
    res = await fetch(path, {
      method,
      headers,
      body: body !== undefined ? JSON.stringify(body) : undefined
    });
  } catch (e) {
    return { status: 0, ok: false, data: {} };
  }
  let data = {};
  try {
    data = await res.json();
  } catch (e) {
    data = {};
  }
  return { status: res.status, ok: res.ok, data };
}

export const unwrapItem = (r) => (r.data && r.data.item ? r.data.item : {});
export const unwrapItems = (r) => (r.data && Array.isArray(r.data.items) ? r.data.items : []);
import { createContext, useContext, useEffect, useState, useCallback } from "react";
import { api, getToken, setToken, getProfileId, setProfileId } from "./api";

const Ctx = createContext(null);

export function useApp() {
  return useContext(Ctx);
}

export function AppProvider({ children }) {
  const [user, setUser] = useState(null);
  const [profile, setProfile] = useState(null);
  const [profiles, setProfiles] = useState([]);
  const [booted, setBooted] = useState(false);

  const load = useCallback(async () => {
    if (!getToken()) {
      setBooted(true);
      return;
    }
    const r = await api("/api/profiles");
    if (r.status === 401 || r.status === 0) {
      setToken(null);
      setBooted(true);
      return;
    }
    const items = r.data.items || [];
    setProfiles(items);
    const me = await api("/api/me");
    if (me.ok && me.data.item) setUser(me.data.item);
    const saved = getProfileId();
    const prof = items.find((p) => String(p.id) === String(saved)) || items[0] || null;
    if (prof) {
      setProfile(prof);
      setProfileId(prof.id);
    }
    setBooted(true);
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const login = useCallback(async (email, password) => {
    const r = await api("/auth/login", { method: "POST", body: { email, password } });
    if (!r.ok) return { ok: false, error: r.data.detail || "Sign in failed" };
    setToken(r.data.access_token);
    return { ok: true };
  }, []);

  const register = useCallback(async (email, password, name) => {
    const r = await api("/auth/register", {
      method: "POST",
      body: { email, password, name: name || email.split("@")[0] }
    });
    if (!r.ok) return { ok: false, error: r.data.detail || "Sign up failed" };
    setToken(r.data.access_token);
    return { ok: true };
  }, []);

  const logout = useCallback(() => {
    setToken(null);
    setProfileId(null);
    setUser(null);
    setProfile(null);
    setProfiles([]);
  }, []);

  const selectProfile = useCallback((p) => {
    setProfile(p);
    setProfileId(p.id);
  }, []);

  const refreshProfiles = useCallback(async () => {
    const r = await api("/api/profiles");
    if (r.ok) {
      const items = r.data.items || [];
      setProfiles(items);
      return items;
    }
    return profiles;
  }, [profiles]);

  return (
    <Ctx.Provider
      value={{
        user, profile, profiles, booted,
        login, register, logout, selectProfile, refreshProfiles, load
      }}
    >
      {children}
    </Ctx.Provider>
  );
}
import { useEffect, useState } from "react";
import { Routes, Route, Navigate, Outlet, useLocation } from "react-router-dom";
import { useApp } from "./store";
import { getToken } from "./api";
import Header from "./components/Header";
import TitleModal from "./components/TitleModal";
import RateDialog from "./components/RateDialog";
import Landing from "./pages/Landing";
import Login from "./pages/Login";
import Register from "./pages/Register";
import Profiles from "./pages/Profiles";
import Home from "./pages/Home";
import Shows from "./pages/Shows";
import Movies from "./pages/Movies";
import Games from "./pages/Games";
import NewPopular from "./pages/NewPopular";
import GenreCategory from "./pages/GenreCategory";
import MyList from "./pages/MyList";
import BrowseLanguages from "./pages/BrowseLanguages";
import TitleDetail from "./pages/TitleDetail";
import PlayerPage from "./pages/PlayerPage";
import NotFound from "./pages/NotFound";
import Account from "./pages/Account";

export const openTitleModal = (id) => {
  window.dispatchEvent(new CustomEvent("nf:open-title", { detail: { id } }));
};

function Guard({ children, needProfile = true }) {
  const { profile, booted } = useApp();
  const loc = useLocation();
  if (!booted) return <div className="min-h-screen bg-nfg" />;
  if (!getToken()) return <Navigate to="/login" state={{ from: loc.pathname }} replace />;
  if (needProfile && !profile) return <Navigate to="/profiles" replace />;
  return children;
}

function BrowseLayout() {
  const { profile } = useApp();
  const [modalId, setModalId] = useState(null);
  const [rateId, setRateId] = useState(null);

  useEffect(() => {
    const onOpen = (e) => setModalId(e.detail.id);
    const onRate = (e) => setRateId(e.detail.id);
    window.addEventListener("nf:open-title", onOpen);
    window.addEventListener("nf:rate", onRate);
    return () => {
      window.removeEventListener("nf:open-title", onOpen);
      window.removeEventListener("nf:rate", onRate);
    };
  }, []);

  useEffect(() => {
    if (!modalId) return;
    const onKey = (e) => e.key === "Escape" && setModalId(null);
    window.addEventListener("keydown", onKey);
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
    };
  }, [modalId]);

  return (
    <div className="min-h-screen bg-nfg">
      <Header />
      <main>
        <Outlet />
      </main>
      {modalId && profile && <TitleModal id={modalId} onClose={() => setModalId(null)} />}
      {rateId && profile && <RateDialog titleId={rateId} onClose={() => setRateId(null)} />}
    </div>
  );
}

export default function App() {
  return (
    <Routes>
      <Route path="/" element={<Landing />} />
      <Route path="/login" element={<Login />} />
      <Route path="/register" element={<Register />} />
      <Route path="/profiles" element={<Guard needProfile={false}><Profiles /></Guard>} />
      <Route element={<Guard><BrowseLayout /></Guard>}>
        <Route path="/browse" element={<Home />} />
        <Route path="/shows" element={<Shows />} />
        <Route path="/movies" element={<Movies />} />
        <Route path="/games" element={<Games />} />
        <Route path="/new" element={<NewPopular />} />
        <Route path="/browse/genre/:genreId" element={<GenreCategory />} />
        <Route path="/browse/languages" element={<BrowseLanguages />} />
        <Route path="/my-list" element={<MyList />} />
        <Route path="/title/:id" element={<TitleDetail />} />
        <Route path="/account" element={<Account />} />
      </Route>
      <Route path="/watch/:titleId" element={<Guard needProfile={false}><PlayerPage /></Guard>} />
      <Route path="*" element={<NotFound />} />
    </Routes>
  );
}

