                            <div className="text-[10px] text-[#777]">{fmt(m.duration)}</div>
                          </div>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )}
              {nextEp && (
                <button
                  onClick={() => { setSeason(nextEp.season); setEpNo(nextEp.number); setEnded(false); }}
                  className="text-white font-medium"
