  rail: "w-[18.3vw] min-w-[150px] aspect-video",
  top16: "w-[15.15vw] min-w-[130px] aspect-video",
  top23: "w-[7.3vw] min-w-[100px] aspect-[2/3]",
  mylist: "w-full aspect-[9/8]",
  lang: "w-full aspect-video",
  grid: "w-full aspect-video"
};

