  if (/^\/api\/genres\/\d+\/titles$/.test(p)) return { items: [T1], total: 1 };
  if (/^\/api\/titles\/\d+\/episodes$/.test(p)) return { items: [EP], total: 1 };
  if (/^\/api\/titles\/\d+$/.test(p)) return { item: T1 };
  if (p === "/api/titles/trending") return { items: [T1, T2], total: 2 };
  if (p === "/api/titles/top10") return { items: [T1, T2], total: 2 };
  if (p === "/api/titles") return { items: [T1, T2], total: 2 };
  if (p === "/api/search") return { items: [T1], total: 1 };
  if (p === "/api/my-list") return { items: [], total: 0 };
  if (method === "POST" && p.startsWith("/auth/")) return { access_token: "tok", token_type: "bearer",
