  ["/browse", "Trending Now", { auth: true, extra: [
      (w) => w.dispatchEvent(new w.CustomEvent("nf:open-title", { detail: { id: 1 } })),
      (w) => w.dispatchEvent(new w.CustomEvent("nf:rate", { detail: { id: 1 } })),
  ] }],
  ["/shows", "TV Shows", { auth: true }],
  ["/movies", "Movies", { auth: true }],
  ["/games", "Party Games", { auth: true }],
  ["/new", "Top 10 TV Shows", { auth: true }],
  ["/browse/genre/1", "Browse", { auth: true }],
  ["/browse/languages", "Browse by Languages", { auth: true }],
  ["/my-list", "Your list is empty", { auth: true }],
  ["/title/1", "Episodes", { auth: true }],
  ["/watch/1", "Series One", { auth: true }],
  ["/account", "Account", { auth: true }],
];

let fails = 0;
for (const [path, expect, opts] of routes) {
  try {
    const { html, routeErrors } = await bootRoute(path, opts);
    const ok = html.length > 200 && (!expect || html.includes(expect)) && routeErrors.length === 0;
    console.log((ok ? "PASS" : "FAIL"), path, !ok ? (routeErrors.join("|") || html.slice(0, 120)) : "");
    if (!ok) fails++;
  } catch (e) { fails++; console.log("FAIL", path, "EXCEPTION", e.message); }
}
// continue-watching progress bar present on /browse
{
  const { html } = await bootRoute("/browse", { auth: true });
  const bar = html.includes("bg-[#e50914]") && /width:\s*5%/.test(html);
  console.log((bar ? "PASS" : "FAIL"), "cw-progress-bar", bar ? "" : "(no 5% progress bar)");
  if (!bar) fails++;
}
// seek input has the styled class
{
  const { html } = await bootRoute("/watch/1", { auth: true });
  const seek = html.includes('class="absolute left-0 top-1/2 -translate-y-1/2 w-full cursor-pointer seek"');
  console.log((seek ? "PASS" : "FAIL"), "seek-styled");
  if (!seek) fails++;
}
console.log(fails === 0 ? "\nALL ROUTES OK" : `\n${fails} FAILURES`);
process.exit(fails ? 1 : 0);
EOF
