  if (p === "/api/continue-watching") return { items: [{ ...T1, id: 1, title_id: 1, progress_seconds: 900 }], total: 1 };
  if (p === "/api/ratings") return { items: [], total: 0 };
  if (p === "/api/genres") return { items: [{ id: 1, name: "Drama" }, { id: 2, name: "Comedy" }], total: 2 };
  if (/^\/api\/genres\/\d+\/titles$/.test(p)) return { items: [T1], total: 1 };
  if (/^\/api\/titles\/\d+\/episodes$/.test(p)) return { items: [EP], total: 1 };
  if (/^\/api\/titles\/\d+$/.test(p)) return { item: T1 };
  if (p === "/api/titles/trending") return { items: [T1, T2], total: 2 };
  if (p === "/api/titles/top10") return { items: [T1, T2], total: 2 };
  if (p === "/api/titles") return { items: [T1, T2], total: 2 };
  if (p === "/api/search") return { items: [T1], total: 1 };
  if (p === "/api/my-list") return { items: [], total: 0 };
  if (method === "POST" && p.startsWith("/auth/")) return { access_token: "tok", token_type: "bearer",
    user: { id: 1, email: "a@x.com", name: "Alex" }, profile: PROF };
  if (method === "POST") return { item: { id: 1, title_id: 1, profile_id: 1, value: 2, progress_seconds: 5 } };
  return { items: [], total: 0 };
}

async function bootRoute(path, { auth = false, extra = [] } = {}) {
  const dom = new JSDOM("<!doctype html><html><body><div id='root'></div></body></html>", {
    url: "http://localhost" + path, runScripts: "outside-only", pretendToBeVisual: true
  });
  const w = dom.window;
  const routeErrors = [];
  w.addEventListener("error", (e) => routeErrors.push("window: " + e.message));
  if (auth) w.localStorage.setItem("nf_token", "tok");
  w.fetch = (input, init = {}) => {
    const url = typeof input === "string" ? input : input.url;
    const method = (init.method || "GET").toUpperCase();
    return Promise.resolve({ ok: true, status: 200,
      json: () => Promise.resolve(apiJson(url, method)),
      text: () => Promise.resolve(JSON.stringify(apiJson(url, method))) });
  };
  w.HTMLMediaElement.prototype.play = () => Promise.resolve();
  w.HTMLMediaElement.prototype.pause = () => Promise.resolve();
  w.eval(BUNDLE);
  w.__boot();
  const settle = (ms) => new Promise((r) => setTimeout(r, ms));
  await settle(250);
  for (const fn of extra) { try { await fn(w); } catch (e) { routeErrors.push("extra: " + e.message); } }
  await settle(600);
  return { html: w.document.getElementById("root").innerHTML, routeErrors };
}

const routes = [
  ["/", "Unlimited movies", {}],
  ["/login", "Enter your info to sign in", {}],
  ["/register", "Sign Up", {}],
  ["/profiles", "Who's watching?", { auth: true }],
  ["/browse", "Trending Now", { auth: true, extra: [
      (w) => w.dispatchEvent(new w.CustomEvent("nf:open-title", { detail: { id: 1 } })),
      (w) => w.dispatchEvent(new w.CustomEvent("nf:rate", { detail: { id: 1 } })),
  ] }],
  ["/shows", "TV Shows", { auth: true }],
  ["/movies", "Movies", { auth: true }],
  ["/games", "Party Games", { auth: true }],
  ["/new", "Top 10 TV Shows", { auth: true }],
  ["/browse/genre/1", "Browse", { auth: true }],
  ["/browse/languages", "Browse by Languages", { auth: true }],
  ["/my-list", "Your list is empty", { auth: true }],
  ["/title/1", "Episodes", { auth: true }],
  ["/watch/1", "Series One", { auth: true }],
  ["/account", "Account", { auth: true }],
];

let fails = 0;
for (const [path, expect, opts] of routes) {
  try {
    const { html, routeErrors } = await bootRoute(path, opts);
    const ok = html.length > 200 && (!expect || html.includes(expect)) && routeErrors.length === 0;
    console.log((ok ? "PASS" : "FAIL"), path, !ok ? (routeErrors.join("|") || html.slice(0, 120)) : "");
    if (!ok) fails++;
  } catch (e) { fails++; console.log("FAIL", path, "EXCEPTION", e.message); }
}
// continue-watching progress bar present on /browse
{
  const { html } = await bootRoute("/browse", { auth: true });
  const bar = html.includes("bg-[#e50914]") && /width:\s*5%/.test(html);
  console.log((bar ? "PASS" : "FAIL"), "cw-progress-bar", bar ? "" : "(no 5% progress bar)");
  if (!bar) fails++;
}
// seek input has the styled class
{
  const { html } = await bootRoute("/watch/1", { auth: true });
  const seek = html.includes('class="absolute left-0 top-1/2 -translate-y-1/2 w-full cursor-pointer seek"');
  console.log((seek ? "PASS" : "FAIL"), "seek-styled");
  if (!seek) fails++;
}
console.log(fails === 0 ? "\nALL ROUTES OK" : `\n${fails} FAILURES`);
process.exit(fails ? 1 : 0);
